// O gatilho é um elemento que já existe; o balão se prende a ele.
const gatilho = createButton({
  variant: 'ghost',
  size: 'icon',
  ariaLabel: 'Salvar',
  children: iconeSalvar,
});

const balao = createTooltip({
  trigger: gatilho,
  content: 'Salvar (Ctrl+S)',   // string vira texto; para marcação, passe um elemento
  side: 'top',                    // top | bottom | left | right
  delayDuration: 400,             // ms de espera antes de o balão aparecer
});

// Solta o portal e os ouvintes do gatilho.
balao.destroy();

extensibilityCode.vanilla:
// Um grupo de balões com espera compartilhada.
const { createTooltip } = createTooltipProvider({
  delayDuration: 400,
  skipDelayDuration: 250,   // dentro da janela, o próximo balão abre sem esperar
});

// Marcação entra como ELEMENTO já montado, nunca como HTML em string.
const texto = document.createElement('span');
texto.append('Salvar ');
const tecla = document.createElement('kbd');
tecla.textContent = 'Ctrl+S';
texto.appendChild(tecla);

const balao = createTooltip({
  trigger: gatilho,
  content: texto,
  side: 'bottom',
  delayDuration: 200,   // sobrepõe a espera do grupo neste balão
  // Disparado quando o balão aparece de fato, depois da espera.
  onShow: () => track('tooltip_shown', { component: 'tooltip' }),
});

