  trigger: gatilho,
  content: text,
  side: 'bottom',
  delayDuration: 200,   // overrides the group wait for this bubble
  // Fires when the bubble is actually shown, after the wait.
  onShow: () => track('tooltip_shown', { component: 'tooltip' }),
});

